const i=[{id:"hypertension-001",topicId:"hypertension",question:"Что такое артериальная гипертензия (АГ)?",options:["Стойкое повышение артериального давления более 140/90 мм рт. ст. при повторных измерениях","Однократное повышение давления после физической нагрузки","Снижение артериального давления ниже 90/60 мм рт. ст.","Нарушение сердечного ритма"],correctIndex:0,explanation:"Артериальная гипертензия — это стойкое повышение артериального давления более 140/90 мм рт. ст. при повторных измерениях.",difficulty:"medium",tags:["гипертензия","определение","АД"]},{id:"hypertension-002",topicId:"hypertension",question:"Выше какого значения артериального давления говорят об артериальной гипертензии?",options:["140/90 мм рт. ст.","120/80 мм рт. ст.","160/100 мм рт. ст.","130/85 мм рт. ст."],correctIndex:0,explanation:"Об артериальной гипертензии говорят при стойком повышении АД более 140/90 мм рт. ст. при повторных измерениях.",difficulty:"medium",tags:["гипертензия","АД","критерий"]},{id:"hypertension-003",topicId:"hypertension",question:"Какой вид артериальной гипертензии является первичным (эссенциальным)?",options:["Гипертензия, причина которой неизвестна (≈90–95% случаев)","Гипертензия как следствие болезни почек","Гипертензия из-за опухоли надпочечников","Гипертензия при эндокринных нарушениях"],correctIndex:0,explanation:"Первичная (эссенциальная) гипертензия — это гипертензия, причина которой неизвестна; составляет примерно 90–95% случаев.",difficulty:"medium",tags:["гипертензия","первичная","виды"]},{id:"hypertension-004",topicId:"hypertension",question:"Какую долю случаев составляет первичная (эссенциальная) гипертензия?",options:["≈ 90–95%","≈ 50%","≈ 20–30%","≈ 5–10%"],correctIndex:0,explanation:"Первичная (эссенциальная) гипертензия составляет примерно 90–95% всех случаев.",difficulty:"hard",tags:["гипертензия","первичная","частота"]},{id:"hypertension-005",topicId:"hypertension",question:"Чем характеризуется вторичная (симптоматическая) гипертензия?",options:["Является следствием болезни почек, эндокринных нарушений, опухолей надпочечников и др.","Возникает без какой-либо известной причины","Развивается только у спортсменов","Является нормальным состоянием организма"],correctIndex:0,explanation:"Вторичная (симптоматическая) гипертензия — следствие болезни почек, эндокринных нарушений, опухолей надпочечников и др.",difficulty:"medium",tags:["гипертензия","вторичная","виды"]},{id:"hypertension-006",topicId:"hypertension",question:"Какой из перечисленных факторов является фактором риска артериальной гипертензии?",options:["Избыточное потребление соли","Низкий уровень холестерина","Высокая физическая активность","Достаточное потребление калия и магния"],correctIndex:0,explanation:"К факторам риска АГ относятся избыточное потребление соли, ожирение, гиподинамия, стрессы, курение, алкоголь, неправильное питание, диабет, дислипидемия, недостаток калия/магния/кальция.",difficulty:"medium",tags:["гипертензия","факторы риска","соль"]},{id:"hypertension-007",topicId:"hypertension",question:"Недостаток каких минералов в питании является фактором риска гипертензии?",options:["Калия, магния, кальция","Железа, цинка, меди","Йода, селена, фтора","Натрия, хлора, фосфора"],correctIndex:0,explanation:"Недостаток калия, магния и кальция в питании является одним из факторов риска артериальной гипертензии.",difficulty:"hard",tags:["гипертензия","факторы риска","минералы"]},{id:"hypertension-008",topicId:"hypertension",question:"Какой симптом характерен для артериальной гипертензии?",options:["Головная боль в затылке, чаще по утрам","Боль в правом подреберье после еды","Резкая боль в суставах","Высокая температура с ознобом"],correctIndex:0,explanation:"Симптомы АГ: головная боль (затылок, утром), головокружение, шум в ушах, учащённое сердцебиение, утомляемость, мелькание «мушек» перед глазами; иногда протекает бессимптомно.",difficulty:"medium",tags:["гипертензия","симптомы","головная боль"]},{id:"hypertension-009",topicId:"hypertension",question:"Какая особенность течения характерна для артериальной гипертензии, особенно на ранних стадиях?",options:["Иногда протекает бессимптомно","Всегда сопровождается потерей сознания","Всегда вызывает сильную боль в груди","Проявляется только высокой температурой"],correctIndex:0,explanation:"Артериальная гипертензия иногда протекает бессимптомно, особенно на ранних стадиях.",difficulty:"medium",tags:["гипертензия","симптомы","бессимптомное течение"]},{id:"hypertension-010",topicId:"hypertension",question:"Какое из перечисленных является осложнением артериальной гипертензии?",options:["Гипертрофия левого желудочка","Железодефицитная анемия","Гемофилия","Талассемия"],correctIndex:0,explanation:"Осложнения АГ: инсульт, инфаркт миокарда, сердечная и почечная недостаточность, гипертрофия левого желудочка, повреждение сосудов глаз (ретинопатия).",difficulty:"medium",tags:["гипертензия","осложнения","гипертрофия"]},{id:"hypertension-011",topicId:"hypertension",question:"Как называется повреждение сосудов глаз как осложнение артериальной гипертензии?",options:["Ретинопатия","Катаракта","Глаукома","Конъюнктивит"],correctIndex:0,explanation:"Повреждение сосудов глаз при АГ называется ретинопатией.",difficulty:"hard",tags:["гипертензия","осложнения","ретинопатия"]},{id:"hypertension-012",topicId:"hypertension",question:"Как называется прибор, определяющий артериальное давление?",options:["Тонометр","Термометр","Глюкометр","Спирометр"],correctIndex:0,explanation:"Прибор, определяющий артериальное давление, называется тонометром (в слайде — «танометр»).",difficulty:"easy",tags:["гипертензия","тонометр","измерение"]},{id:"hypertension-013",topicId:"hypertension",question:"Какие значения систолического и диастолического АД соответствуют норме согласно таблице категорий?",options:["90–119 / 60–79","120–139 / 80–89","140–159 / 90–99","≥180 / ≥110"],correctIndex:0,explanation:"По таблице категорий норма соответствует систолическому АД 90–119 и диастолическому 60–79 мм рт. ст.",difficulty:"hard",tags:["гипертензия","категории АД","норма"]},{id:"hypertension-014",topicId:"hypertension",question:"Какие значения АД соответствуют категории «высокая норма»?",options:["120–139 / 80–89","90–119 / 60–79","140–159 / 90–99","160–179 / 100–109"],correctIndex:0,explanation:"Категория «высокая норма» соответствует систолическому АД 120–139 и диастолическому 80–89 мм рт. ст.",difficulty:"hard",tags:["гипертензия","категории АД","высокая норма"]},{id:"hypertension-015",topicId:"hypertension",question:"Какие значения АД соответствуют 1-й стадии артериальной гипертензии?",options:["140–159 / 90–99","120–139 / 80–89","160–179 / 100–109","≥180 / ≥110"],correctIndex:0,explanation:"1-я стадия АГ соответствует систолическому АД 140–159 и диастолическому 90–99 мм рт. ст.",difficulty:"hard",tags:["гипертензия","категории АД","1-я стадия"]},{id:"hypertension-016",topicId:"hypertension",question:"Какие значения АД соответствуют 2-й стадии артериальной гипертензии?",options:["160–179 / 100–109","140–159 / 90–99","120–139 / 80–89","≥180 / ≥110"],correctIndex:0,explanation:"2-я стадия АГ соответствует систолическому АД 160–179 и диастолическому 100–109 мм рт. ст.",difficulty:"hard",tags:["гипертензия","категории АД","2-я стадия"]},{id:"hypertension-017",topicId:"hypertension",question:"Какие значения АД соответствуют 3-й стадии артериальной гипертензии?",options:["≥180 / ≥110","160–179 / 100–109","140–159 / 90–99","120–139 / 80–89"],correctIndex:0,explanation:"3-я стадия АГ соответствует систолическому АД ≥180 и диастолическому ≥110 мм рт. ст.",difficulty:"hard",tags:["гипертензия","категории АД","3-я стадия"]},{id:"hypertension-018",topicId:"hypertension",question:"Как называются группы препаратов против гипертонии?",options:["Антигипертензивные","Антианемические","Гемостатические","Антитромботические"],correctIndex:0,explanation:"Группы препаратов против гипертонии называются антигипертензивными.",difficulty:"medium",tags:["гипертензия","лечение","антигипертензивные"]},{id:"hypertension-019",topicId:"hypertension",question:"Какая из перечисленных групп относится к антигипертензивным препаратам?",options:["Ингибиторы АПФ","Статины","Гемостатики","Антианемические препараты"],correctIndex:0,explanation:"К антигипертензивным относятся 4 группы: блокаторы кальциевых каналов, бета-адреноблокаторы, диуретики и ингибиторы АПФ.",difficulty:"medium",tags:["гипертензия","лечение","группы препаратов"]},{id:"hypertension-020",topicId:"hypertension",question:"Сколько основных групп антигипертензивных препаратов выделяют в материале?",options:["4","2","6","3"],correctIndex:0,explanation:"Выделяют 4 группы антигипертензивных препаратов: блокаторы кальциевых каналов, бета-адреноблокаторы, диуретики, ингибиторы АПФ.",difficulty:"medium",tags:["гипертензия","лечение","классификация"]},{id:"hypertension-021",topicId:"hypertension",question:"К какой группе антигипертензивных препаратов относятся нифедипин, амлодипин и верапамил?",options:["Блокаторы кальциевых каналов","Бета-адреноблокаторы","Диуретики","Ингибиторы АПФ"],correctIndex:0,explanation:"Нифедипин, амлодипин, верапамил, нимодипин и дилтиазем относятся к блокаторам кальциевых каналов.",difficulty:"medium",tags:["гипертензия","блокаторы кальциевых каналов","нифедипин"]},{id:"hypertension-022",topicId:"hypertension",question:"Под каким торговым названием выпускается нифедипин?",options:["Коринфар","Амловас","Изоптин","Нимотоп"],correctIndex:0,explanation:"Нифедипин (10 мг, 20 мг) выпускается под торговым названием Коринфар.",difficulty:"hard",tags:["гипертензия","блокаторы кальциевых каналов","нифедипин"]},{id:"hypertension-023",topicId:"hypertension",question:"Под каким торговым названием выпускается амлодипин?",options:["Амловас","Коринфар","Изоптин","Дилтиам"],correctIndex:0,explanation:"Амлодипин (5 мг, 10 мг) выпускается под торговым названием Амловас.",difficulty:"hard",tags:["гипертензия","блокаторы кальциевых каналов","амлодипин"]},{id:"hypertension-024",topicId:"hypertension",question:"Под каким торговым названием выпускается верапамил?",options:["Изоптин","Амловас","Коринфар","Нимотоп"],correctIndex:0,explanation:"Верапамил (20 мг, 40 мг) выпускается под торговым названием Изоптин.",difficulty:"hard",tags:["гипертензия","блокаторы кальциевых каналов","верапамил"]},{id:"hypertension-025",topicId:"hypertension",question:"Какой блокатор кальциевых каналов выпускается под торговым названием Нимотоп?",options:["Нимодипин","Нифедипин","Амлодипин","Дилтиазем"],correctIndex:0,explanation:"Нимодипин (10 мг, 30 мг) выпускается под торговым названием Нимотоп.",difficulty:"hard",tags:["гипертензия","блокаторы кальциевых каналов","нимодипин"]},{id:"hypertension-026",topicId:"hypertension",question:"Какой блокатор кальциевых каналов выпускается под торговым названием Дилтиам?",options:["Дилтиазем","Верапамил","Нифедипин","Амлодипин"],correctIndex:0,explanation:"Дилтиазем (60 мг, 90 мг) выпускается под торговым названием Дилтиам.",difficulty:"hard",tags:["гипертензия","блокаторы кальциевых каналов","дилтиазем"]},{id:"hypertension-027",topicId:"hypertension",question:"Какое осложнение со стороны головного мозга может развиться при артериальной гипертензии?",options:["Инсульт","Менингит","Мигрень","Энцефалит"],correctIndex:0,explanation:"Одним из осложнений артериальной гипертензии со стороны мозга является инсульт.",difficulty:"medium",tags:["гипертензия","осложнения","инсульт"]},{id:"hypertension-028",topicId:"hypertension",question:"Какие из перечисленных вредных привычек являются факторами риска гипертензии?",options:["Курение и употребление алкоголя","Регулярные физические упражнения","Употребление продуктов, богатых калием","Снижение массы тела"],correctIndex:0,explanation:"Курение и алкоголь входят в список факторов риска артериальной гипертензии наряду с ожирением, гиподинамией, стрессами и неправильным питанием.",difficulty:"easy",tags:["гипертензия","факторы риска","вредные привычки"]},{id:"hypertension-029",topicId:"hypertension",question:"Какие сопутствующие заболевания являются факторами риска артериальной гипертензии?",options:["Сахарный диабет и дислипидемия","Гемофилия и талассемия","Анемия и лейкоз","Гастрит и язвенная болезнь"],correctIndex:0,explanation:"Сахарный диабет и дислипидемия (высокий холестерин) входят в число факторов риска артериальной гипертензии.",difficulty:"medium",tags:["гипертензия","факторы риска","диабет"]},{id:"hypertension-030",topicId:"hypertension",question:"Что из перечисленного НЕ относится к симптомам артериальной гипертензии?",options:["Деформация костей и задержка роста","Головокружение и шум в ушах","Учащённое сердцебиение","Мелькание «мушек» перед глазами"],correctIndex:0,explanation:"Деформация костей и задержка роста — это симптомы талассемии, а не гипертензии. Симптомы АГ: головная боль, головокружение, шум в ушах, учащённое сердцебиение, утомляемость, «мушки» перед глазами.",difficulty:"medium",tags:["гипертензия","симптомы","найди ошибку"]},{id:"hypertension-031",topicId:"hypertension",question:"Какие осложнения со стороны органов-мишеней характерны для артериальной гипертензии?",options:["Сердечная и почечная недостаточность","Гипокалиемия и алкалоз","Гемартрозы и синяки","Желтуха и спленомегалия"],correctIndex:0,explanation:"К осложнениям АГ относятся сердечная и почечная недостаточность, а также инсульт, инфаркт миокарда, гипертрофия левого желудочка и ретинопатия.",difficulty:"medium",tags:["гипертензия","осложнения","недостаточность"]},{id:"hypertension-032",topicId:"hypertension",question:"Систолическое АД при какой категории впервые достигает 140 мм рт. ст. и выше?",options:["1-я стадия гипертензии","Высокая норма","Норма","2-я стадия гипертензии"],correctIndex:0,explanation:"Систолическое АД 140 мм рт. ст. и выше (140–159) соответствует 1-й стадии гипертензии; «высокая норма» — это 120–139.",difficulty:"hard",tags:["гипертензия","категории АД","стадии"]}];export{i as default};
